insert into words (deck_id, term, translation, "order", image_url)
select d.id, v.t, v.tr, v.o, case when v.k = '' then null else (
  select x.image_url from words x join word_decks xd on xd.id = x.deck_id and xd.deleted_at is null
  where x.image_url is not null and lower(trim(x.term)) = lower(trim(v.t))
    and (v.k = 's' or (select coalesce(array_agg(distinct left(w,4)),'{}') from regexp_split_to_table(replace(lower(coalesce(x.translation,'')),'ё','е'), '[^а-я]+') w
  where length(w)>=3 and w not in ('что','кто','кого','чем','чего','либо','нибудь','себя','свой','быть','очень','такой','этот','который')) && (select coalesce(array_agg(distinct left(w,4)),'{}') from regexp_split_to_table(replace(lower(coalesce(v.tr,'')),'ё','е'), '[^а-я]+') w
  where length(w)>=3 and w not in ('что','кто','кого','чем','чего','либо','нибудь','себя','свой','быть','очень','такой','этот','который')))
  order by x.id desc limit 1) end
from (values ('Module 8: Challenges', false, '8c', 'painkiller', 'болеутоляющее средство, обезболивающее', 4, ''), ('Module 8: Challenges', false, '8c', 'plaster', 'пластырь', 5, ''), ('Module 8: Challenges', false, '8c', 'shrink', 'уменьшаться, сжиматься', 6, ''), ('Module 8: Challenges', false, '8c', 'sore throat', 'больное горло', 7, ''), ('Module 8: Challenges', false, '8c', 'threaten', 'угрожать, грозить', 8, 'r'), ('Module 8: Challenges', false, '8c', 'warn', 'предупреждать, предостерегать', 9, 'r'), ('Module 8: Challenges', false, '8d Survival & Equipment · фразы', 'antiseptic cream', 'антисептический крем', 1, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · понятия', 'bandage', 'бинт, повязка', 1, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · понятия', 'cast', 'гипс', 2, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · действия', 'crash', 'разбивать(ся)', 1, 'r'), ('Module 8: Challenges', false, '8d Survival & Equipment · понятия', 'creepy-crawly', 'ползучая тварь (о насекомом), страшное противное насекомое', 3, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · фразы', 'do the trick', 'добиться своего, достичь цели', 2, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · понятия', 'first aid kit', 'медицинская аптечка', 4, 'r'), ('Module 8: Challenges', false, '8d Survival & Equipment · действия', 'graze', 'оцарапать, ободрать', 2, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · фразы', 'hang on', 'держаться, продержаться, выжить', 3, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · фразы', 'hold (sth) up', 'поддерживать что-либо', 4, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · понятия', 'ice pack', 'пузырь со льдом', 5, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · фразы', 'insect repellent', 'средство для отпугивания насекомых', 5, ''), ('Module 8: Challenges', false, '8d Survival & Equipment · описание', 'juicy', 